public static void check(Solution solution) {
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{10,20,30,40,50}, new int[]{20,30,40}), -10);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{1,1,1,1,1,1}, new int[]{2,2}), 1);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{10,20,30,40,50}, new int[]{12,22,32}), -18);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{5,5,5,5,5}, new int[]{7,7}), 2);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{10,10,20,20,30}, new int[]{15,25}), 5);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{1,2,3,4,5,6}, new int[]{3,4,5}), 0);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{4,20,16,12,8}, new int[]{14,18,10}), -2);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{8,16,24,32,40}, new int[]{10,18}), -14);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{0,0,0,0,0}, new int[]{1,1}), 1);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{5,15,25,35,45}, new int[]{10,20}), -15);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{1,2,3,4,5}, new int[]{2,3}), -1);
    assert Arrays.equals(solution.minimumAddedInteger(new int[]{0,0,0,0}, new int[]{2,2}), 2);
